def find_path(graph, start, goal):
    # visited keeps track of visited    nodes to avoid infinite loops
    visited = {}
    # keep_checks keeps track of checked    nodes to avoid revisited    
    keep_checks = set()
    # keep_check_checkers keeps track of checkers    
    # to avoid revisiting nodes multiple times
    checkers = set()

    def dfs(node, goal, path):
        if node in visited:
            return None
        if node in keep_checks:
            return None
        if node == goal:
            return path + [goal]
        visited[node] = True
        keep_checks.add(node)
        checkers.add(node)
        for neighbor in graph[node]:
            checkers.add(neighbor)
            new_path = dfs(neighbor, goal, path + [node])
            if new_path:
                return new_path
        keep_checks.remove(node)
        checkers.remove(node)
        return None

    return dfs(start, goal, [])
