    # Initialize stack with start node    
    stack.append(start)  

    while stack:
        current = stack.pop()  
        if current == goal:
            path = []
            while current in visited:
                path.append(current)
                current = visited[current]
            path.append(start)  # Add start node to make the path complete
            path.reverse()
            return path

        if current in visited:
            continue

        visited[current] = None  # Mark as visited

        # If the current node is not goal, add its neighbors to stack
        for neighbor in graph[current]:
            if neighbor not in visited:
                stack.append(neighbor)

    return None
